"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"

const continents = [
  { id: "all", label: "전체", labelEn: "All" },
  { id: "asia", label: "아시아", labelEn: "Asia" },
  { id: "europe", label: "유럽", labelEn: "Europe" },
  { id: "north-america", label: "북미", labelEn: "North America" },
  { id: "south-america", label: "남미", labelEn: "South America" },
  { id: "oceania", label: "오세아니아", labelEn: "Oceania" },
  { id: "africa", label: "아프리카", labelEn: "Africa" },
]

export function CityFilter() {
  const [activeFilter, setActiveFilter] = useState("all")

  return (
    <div className="mb-12">
      <h2 className="text-3xl font-bold mb-8 text-center">도시 탐색하기</h2>
      <div className="flex flex-wrap gap-3 justify-center">
        {continents.map((continent) => (
          <Button
            key={continent.id}
            variant={activeFilter === continent.id ? "default" : "outline"}
            onClick={() => setActiveFilter(continent.id)}
            className="transition-all"
          >
            {continent.label}
          </Button>
        ))}
      </div>
    </div>
  )
}
